package run.ikaros.planning; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/planning/tasks/{taskId}/assignments") public class PlanningTaskAssignmentController {private final PlanningTaskAssignmentService service;public PlanningTaskAssignmentController(PlanningTaskAssignmentService s){service=s;} @PostMapping public Mono<PlanningTaskAssignmentView> assign(@RequestHeader("X-Ikaros-Actor-Id")UUID owner,@PathVariable UUID taskId,@Valid@RequestBody AssignPlanningTaskRequest r){return service.assign(owner,taskId,r);}@GetMapping public Flux<PlanningTaskAssignmentView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID owner,@PathVariable UUID taskId){return service.list(owner,taskId);}@DeleteMapping("/{assigneeId}")public Mono<Void> unassign(@RequestHeader("X-Ikaros-Actor-Id")UUID owner,@PathVariable UUID taskId,@PathVariable UUID assigneeId){return service.unassign(owner,taskId,assigneeId);}}
